const item=$input.item.json;
const sourceName=item['Source Name']||'';
const fileUrl=item['Ebook_Source_File_URL']||'';
const existingNotes=item['Notes']||'';
const rawOverride=item['Skill Picker'];
const skillOverride=(typeof rawOverride==='string'?rawOverride:(rawOverride&&rawOverride.name)||'').trim();
const STAGE_TAG='EBOOK LINKEDIN POSTS (skill)';
const sep='==============================';
const blockRe=new RegExp('\\n*'+sep+'\\n'+STAGE_TAG.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'[\\s\\S]*?(?=(\\n'+sep+'\\n)|$)','g');
const notesBase=existingNotes.replace(blockRe,'').trim();
return{json:{record_id:item.id||'',source_name:sourceName,topic:sourceName,ebook_file_url:fileUrl,notes_base:notesBase,stage_tag:STAGE_TAG,sep,has_file:!!(fileUrl&&fileUrl.trim().length>5),skill_override:skillOverride}};

const d=$input.item.json;
const folderUrl=d.drive_folder_url||'';
const folderId=d.sub_folder_id||'';
const fileUrl=d.ebook_file_url||'';
const base=(d.subfolder_name||'alfredai');
const files=[base+'_dense-editorial-infographic.png',base+'_governance-system.png',base+'_human-plus-ai-field-note.png'];
const msg='SOURCE (reference material only, not the subject of the post). This is a finished AlfredAI eBook PDF. Read it in full and treat it as the supplied source in place of a source link:
'+fileUrl+'

Run your skill end to end on this source. The skill owns everything: research order, reader and CTA rotation, story shape, visual family and subformat selection, copy, density and proportion, wordmark compositing, and the delivery gate. Do not ask for direction and do not wait for approval. Follow the skill exactly as written.

Apply your source-link triple pack workflow to this eBook. Produce all three packages: one Dense Editorial Infographic, one Governance System, and one Human-plus-AI Field Note. Each needs its own 4:5 graphic at 1664 x 2080 px and its own complete LinkedIn caption, each answering a different construction question drawn from the eBook rather than three rewrites of the same insight.

Use Nano Banana Pro (the built-in image generation tool) for all base image generation. Composite the official transparent wordmark from your skill templates as the skill specifies; never let the image model render the wordmark.

DELIVERABLES:
1. The three PNGs, named exactly as listed below.
2. captions.txt containing all three full LinkedIn captions with their hashtags, source links, and the triple-pack source log.

UPLOAD (mandatory final step, do not skip):
DESTINATION_FOLDER_ID: '+folderId+'
DESTINATION_FOLDER_URL: '+folderUrl+'
OUTPUT_FILENAMES:
1. '+files[0]+' (Dense Editorial Infographic)
2. '+files[1]+' (Governance System)
3. '+files[2]+' (Human-plus-AI Field Note)

Upload the three PNGs and captions.txt to Google Drive using rclone, targeting the EXISTING destination folder by ID with --drive-root-folder-id '+folderId+' so the files land directly INSIDE that existing folder. The destination is a shared drive, so include shared-drive support. Use a single rclone copy for the whole set and run it EXACTLY ONCE; do not re-run, retry, or upload file-by-file in a loop. Do NOT create a new folder. Do NOT use the folder ID as a folder name. Do NOT leave files only in your task workspace.

In your task output, list the four files you placed in that folder, each listed once, and include the three full LinkedIn captions plus the triple-pack source log.';
return{json:{...d,manus_message:msg,output_filenames:files}};

const resp=$input.item.json||{};
const ctx=$('6. Build Manus Message').item.json;
const project='3c8Tpmj5hWFRdgFS8UHb45';
const rec=ctx.record_id||'(no id)';
if(resp.ok===false||!Array.isArray(resp.data)){throw new Error('skill.list failed for Manus project '+project+' on record '+rec+': '+JSON.stringify(resp).substring(0,300)+'. Nothing submitted.');}
const all=resp.data.filter(Boolean);
const norm=s=>String(s||'').trim().toLowerCase();
const DEFAULT_SKILL='alfredai-diverse-linkedin-graphics';
const override=String(ctx.skill_override||'').trim();
const wanted=override||DEFAULT_SKILL;
const source=override?'record override':'default';
const projectSkills=all.filter(s=>s.owner_type==='project');
const matches=projectSkills.filter(s=>norm(s.name)===norm(wanted));
if(matches.length!==1||!matches[0].id){
  const nonProject=all.filter(s=>s.owner_type!=='project'&&norm(s.name)===norm(wanted)).map(s=>(s.owner_type||'unknown')+' '+s.id);
  let why;
  if(matches.length>1)why=matches.length+' project skills share this name ('+matches.map(s=>s.id).join(', ')+')';
  else if(nonProject.length)why='only non-project copies exist ['+nonProject.join(', ')+']; personal, team, official and app skills are not allowed';
  else why='no project skill with this name';
  throw new Error('Skill '+wanted+' ('+source+') not resolved for record '+rec+' in Manus project '+project+': '+why+'. Project skills available: '+(projectSkills.map(s=>s.name).join(', ')||'(none)')+'. Nothing submitted.');
}
const hit=matches[0];
return{json:{...ctx,manus_project_id:project,resolved_skill_id:hit.id,resolved_skill_name:hit.name||wanted,resolved_skill_owner_type:hit.owner_type,resolved_skill_source:source,skill_resolve_error:''}};

